// Des: Map a job name to its code, risk, description
// Flo: legacy jobs (post, reply, dm, ...) and catalog jobs (ru-jobs-tabl) and read lists > exec by name > risk class from code (never the AI)
// I/O: job name + Args (caller) > runs the job; risky(): true when it needs the owner's approval; names() for `fb-face-webs jobs`
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const post = @import("ru-post-main.zig"); const repl = @import("ru-feed-repl.zig"); const dmsg = @import("ru-dmsg-main.zig"); const mark = @import("ru-mark-list.zig"); const jobs = @import("ru-jobs-tabl.zig"); const jrun = @import("ru-jobs-main.zig"); const rdm = @import("ru-read-main.zig");
pub const Row = struct { name: []const u8, risk: u8, kind: []const u8, area: []const u8 = "core", cls: u8 = 0 };
const LEGACY = [_]Row{ .{ .name = "post", .risk = 'w', .kind = "post" }, .{ .name = "page", .risk = 'w', .kind = "post" }, .{ .name = "dm", .risk = 'w', .kind = "dmsg" }, .{ .name = "join", .risk = 'w', .kind = "grou" }, .{ .name = "friend", .risk = 'x', .kind = "frie" }, .{ .name = "reply", .risk = 'w', .kind = "comm" }, .{ .name = "list", .risk = 'w', .kind = "mark" }, .{ .name = "renew", .risk = 'w', .kind = "mark" }, .{ .name = "renewall", .risk = 'w', .kind = "mark" }, .{ .name = "sold", .risk = 'w', .kind = "mark" }, .{ .name = "mark-avail", .risk = 'w', .kind = "mark" }, .{ .name = "mark-relist", .risk = 'w', .kind = "mark" }, .{ .name = "mark-delete", .risk = 'x', .kind = "mark" }, .{ .name = "mark-share", .risk = 'w', .kind = "grou" }, .{ .name = "sale-scan", .risk = 'w', .kind = "mark" }, .{ .name = "msgr-reply", .risk = 'w', .kind = "dmsg" }, .{ .name = "market-reply", .risk = 'w', .kind = "dmsg" } };
pub fn rowCount() usize { return LEGACY.len + jobs.JOBS.len; }
pub fn rowAt(idx: usize) Row { if (idx < LEGACY.len) { var lg = LEGACY[idx]; lg.cls = if (lg.risk == 'x') 'G' else 'A'; return lg; } const jb = jobs.JOBS[idx - LEGACY.len]; return .{ .name = jb.name, .risk = if (jb.risk == .x) 'x' else 'w', .kind = @tagName(jb.kind), .area = @tagName(jb.area), .cls = jobs.classOf(&jb) }; }
pub fn known(name: []const u8) bool { var ix: usize = 0; while (ix < rowCount()) : (ix += 1) { if (std.mem.eql(u8, rowAt(ix).name, name)) return true; } return rdm.kindOf(name) != null; }
pub fn risky(ctx: *task.Ctx, name: []const u8, tsk: task.Args) bool { var ix: usize = 0; while (ix < rowCount()) : (ix += 1) { const rw = rowAt(ix); if (std.mem.eql(u8, rw.name, name)) { if (rw.risk == 'x') return true; break; } } if (std.mem.eql(u8, name, "dm")) { const knw = ctx.store.knowHas(tsk.to) catch false; return !knw; } return false; }
pub fn exec(ctx: *task.Ctx, job: []const u8, tsk: task.Args) !void { execOne(ctx, job, tsk) catch |err| { const live = ctx.mode == .live or ctx.mode == .force; if (err != error.NeedLogin or !live or ctx.relog or ctx.secr.login.len == 0 or std.mem.eql(u8, job, "acct-login")) return err; ctx.relog = true; task.say(ctx, "session expired: logging in again once", .{}); const lj = jobs.find("acct-login") orelse return err; _ = try jrun.run(ctx, lj, .{}); return execOne(ctx, job, tsk); }; }
fn execOne(ctx: *task.Ctx, job: []const u8, tsk: task.Args) !void { if (std.mem.eql(u8, job, "post")) { _ = try post.postRun(ctx, tsk); } else if (std.mem.eql(u8, job, "page")) { _ = try dmsg.pageRun(ctx, tsk); } else if (std.mem.eql(u8, job, "dm")) { _ = try dmsg.dmRun(ctx, tsk); } else if (std.mem.eql(u8, job, "join")) { _ = try dmsg.joinRun(ctx, tsk); } else if (std.mem.eql(u8, job, "friend")) { _ = try dmsg.friendRun(ctx, tsk); } else if (std.mem.eql(u8, job, "reply")) { const cnt = try repl.replRun(ctx, tsk); task.say(ctx, "replies handled: {d}", .{cnt}); } else if (std.mem.eql(u8, job, "list")) { _ = try mark.listRun(ctx, tsk); } else if (std.mem.eql(u8, job, "renew")) { _ = try mark.renewRun(ctx, tsk); } else if (std.mem.eql(u8, job, "renewall")) { const cnt = try mark.renewAll(ctx, tsk); task.say(ctx, "listings renewed: {d}", .{cnt}); } else if (std.mem.eql(u8, job, "sold")) { _ = try mark.soldRun(ctx, tsk); } else if (std.mem.eql(u8, job, "mark-avail")) { _ = try mark.availRun(ctx, tsk); } else if (std.mem.eql(u8, job, "mark-relist")) { _ = try mark.relistRun(ctx, tsk); } else if (std.mem.eql(u8, job, "mark-delete")) { _ = try mark.deleteRun(ctx, tsk); } else if (std.mem.eql(u8, job, "mark-share")) { const cnt = try mark.shareRun(ctx, tsk); task.say(ctx, "shared to {d} groups", .{cnt}); } else if (std.mem.eql(u8, job, "sale-scan")) { const cnt = try mark.saleScan(ctx, tsk); task.say(ctx, "sales seen: {d}", .{cnt}); } else if (std.mem.eql(u8, job, "msgr-reply")) { const cnt = try rdm.msgrReply(ctx, tsk, false); task.say(ctx, "threads answered: {d}", .{cnt}); } else if (std.mem.eql(u8, job, "market-reply")) { const cnt = try rdm.msgrReply(ctx, tsk, true); task.say(ctx, "buyer threads answered: {d}", .{cnt}); } else if (jobs.find(job)) |jb| { const cnt = try jrun.run(ctx, jb, tsk); task.say(ctx, "{s}: {d} done", .{ job, cnt }); } else if (rdm.kindOf(job) != null) { _ = try rdm.readRun(ctx, job); } else return error.NoJob; }
pub fn fromRef(ref: @import("cf-conf-load.zig").JobRef) task.Args { return .{ .text = ref.text, .to = ref.to, .url = ref.url, .title = ref.title, .price = ref.price, .desc = ref.desc, .group = ref.group, .photo = ref.photo, .opt = ref.opt, .date = ref.date, .time = ref.time, .catg = ref.catg, .cond = ref.cond, .loca = ref.loca, .maxn = ref.maxn }; }
